// Draws the KiteVault logo and writes every image the app needs (PNG) plus the SVG sources.
//
//   npm i --no-save @resvg/resvg-js      (a tool for this script only; it is not a dependency)
//   node scripts/build-brand-assets.js
//
// The logo is the Kitelux kite (same four-facet diamond, same colours, same night-blue) with a
// keyhole cut out of it where Kitelux has its sparkle: Kitelux makes the kite, KiteVault locks
// things up. Nothing here is generated by a model: it is plain geometry you can edit by hand.
// The numbers (viewBox 120 x 160) are the ones from the Kitelux logo sheet.
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const OUT_IMAGES = path.join(ROOT, 'assets', 'images');
const OUT_BRANDING = path.join(ROOT, 'assets', 'branding');

// --- brand colours (from the Kitelux sheet) ----------------------------------------------------
const NIGHT = '#0E1630';
const AMBER = '#FFB547';
const FACETS = {
  topLeft: '#FFC861',
  topRight: '#FF9F45',
  bottomLeft: '#FF8A4C',
  bottomRight: '#F2643F',
};
const SEAM = '#7A3412';

// --- the shapes, in the 120 x 160 box of the Kitelux logo ---------------------------------------
const KITE = [
  `<path d="M60 14 L28 46 L60 46 Z" fill="${FACETS.topLeft}"/>`,
  `<path d="M60 14 L92 46 L60 46 Z" fill="${FACETS.topRight}"/>`,
  `<path d="M28 46 L60 104 L60 46 Z" fill="${FACETS.bottomLeft}"/>`,
  `<path d="M92 46 L60 104 L60 46 Z" fill="${FACETS.bottomRight}"/>`,
  `<path d="M60 14 L60 104 M28 46 L92 46" stroke="${SEAM}" stroke-opacity="0.25" stroke-width="1.2" fill="none"/>`,
].join('');

// A keyhole: a round head and a slot that widens downwards. Centred on the kite's middle line.
const KEYHOLE_PATH =
  'M60 37.5 a7.2 7.2 0 0 1 3.1 13.7 L65.6 66 L54.4 66 L56.9 51.2 A7.2 7.2 0 0 1 60 37.5 Z';
const keyhole = (fill) => `<path d="${KEYHOLE_PATH}" fill="${fill}"/>`;

const TAIL = [
  `<path d="M60 104 C54 114 66 122 58 132 C52 140 62 148 56 156" stroke="${AMBER}" stroke-width="2.2" stroke-linecap="round" fill="none"/>`,
  `<path d="M52 114 L59 118 L52 122 Z M66 114 L59 118 L66 122 Z" fill="${FACETS.bottomLeft}"/>`,
  `<path d="M50 136 L57 140 L50 144 Z M64 136 L57 140 L64 144 Z" fill="${AMBER}"/>`,
].join('');

const DIAMOND = 'M60 14 L92 46 L60 104 L28 46 Z';

// Places a piece of the 120 x 160 drawing so that (cx, cy) of the drawing lands at (x, y) of the
// canvas, enlarged by `scale`.
const place = (inner, scale, cx, cy, x, y) =>
  `<g transform="translate(${x - cx * scale} ${y - cy * scale}) scale(${scale})">${inner}</g>`;

const svg = (size, inner, background) =>
  `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 ${size} ${size}">` +
  (background ? `<rect width="${size}" height="${size}" fill="${background}"/>` : '') +
  inner +
  '</svg>';

// --- the pictures ---------------------------------------------------------------------------------
// The middle of the kite (without its tail) is (60, 59). At scale 7 the tips are 315 px from the
// middle of a 1024 canvas: inside the 676 px circle that Android always keeps visible.
const KITE_MIDDLE = [60, 59];
const kiteOnly = KITE + keyhole(NIGHT);

const pictures = {
  // Old-style square icon and the Play Store icon source: full bleed, night background.
  'icon.png': svg(1024, place(kiteOnly, 7, ...KITE_MIDDLE, 512, 512), NIGHT),
  // Adaptive icon: the picture on a transparent layer; Android adds the night-blue background
  // (adaptiveIcon.backgroundColor in app.json), so there is no background image.
  'android-icon-foreground.png': svg(1024, place(kiteOnly, 7, ...KITE_MIDDLE, 512, 512)),
  // Themed (monochrome) icon: only the shape matters; Android colours it. The keyhole is a hole.
  'android-icon-monochrome.png': svg(
    1024,
    `<defs><mask id="hole" maskUnits="userSpaceOnUse" x="0" y="0" width="120" height="160">` +
      `<rect width="120" height="160" fill="#fff"/>${keyhole('#000')}</mask></defs>` +
      place(`<path d="${DIAMOND}" fill="#fff" mask="url(#hole)"/>`, 7, ...KITE_MIDDLE, 512, 512),
  ),
  // Start-up picture: the full logo with its tail, on a transparent layer (the splash colour is set
  // in app.json). Kept inside the middle two thirds because Android 12+ draws it in a circle.
  'splash-icon.png': svg(1024, place(KITE + keyhole(NIGHT) + TAIL, 4.4, 60, 85, 512, 512)),
  // The mark used inside the app (welcome and unlock screens), transparent, with tail.
  'brand-mark.png': svg(512, place(KITE + keyhole(NIGHT) + TAIL, 3.0, 60, 85, 256, 256)),
};

// Vector sources for designers and for the Play Store graphics.
const sources = {
  'kitevault-mark.svg': `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 160" width="240" height="320" role="img" aria-label="KiteVault mark: a kite with a keyhole">${KITE}${keyhole(NIGHT)}${TAIL}</svg>`,
  'kitevault-icon.svg': svg(1024, place(kiteOnly, 7, ...KITE_MIDDLE, 512, 512), NIGHT),
  'kitevault-mark-one-colour.svg': `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 160" width="240" height="320" role="img" aria-label="KiteVault mark in one colour"><defs><mask id="hole"><rect width="120" height="160" fill="#fff"/>${keyhole('#000')}</mask></defs><path d="${DIAMOND}" fill="${NIGHT}" mask="url(#hole)"/><path d="M60 104 C54 114 66 122 58 132 C52 140 62 148 56 156" stroke="${NIGHT}" stroke-width="2.6" stroke-linecap="round" fill="none"/></svg>`,
};

function main() {
  let Resvg;
  try {
    ({ Resvg } = require('@resvg/resvg-js'));
  } catch {
    console.error('Install the drawing tool first:  npm i --no-save @resvg/resvg-js');
    process.exit(1);
  }
  fs.mkdirSync(OUT_IMAGES, { recursive: true });
  fs.mkdirSync(OUT_BRANDING, { recursive: true });
  for (const [name, text] of Object.entries(pictures)) {
    const png = new Resvg(text, { fitTo: { mode: 'original' } }).render().asPng();
    fs.writeFileSync(path.join(OUT_IMAGES, name), png);
    console.log('wrote assets/images/' + name, png.length + ' bytes');
  }
  for (const [name, text] of Object.entries(sources)) {
    fs.writeFileSync(path.join(OUT_BRANDING, name), text + '\n');
    console.log('wrote assets/branding/' + name);
  }
}

main();
